Rewrite the following GNU C++ code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to rewrite:
<original_code>
#include <vector>
#include <list>
#include <map>
#include <set>
#include <deque>
#include <stack>
#include <bitset>
#include <algorithm>
#include <functional>
#include <numeric>
#include <utility>
#include <sstream>
#include <iostream>
#include <iomanip>
#include <cstdio>
#include <cmath>
#include <cstdlib>
#include <ctime>
#include <cstring>
#include <queue>
using namespace std;
#define tr(c,i) for(typeof((c).begin()) i = (c).begin(); i != (c).end(); i++)
using namespace std;
int n,t,counter,source_cap[10][10],sink_cap[10][10],source_num[10][10],sink_num[10][10],plant[10][10][61],flo[200][200];
int dr[]={0,0,-1,1},dc[]={-1,1,0,0};
bool is_valid(int r,int c)
{
	if(r<0 || r>=n || c<0 || c>=n)
		return false;
	return true;
}
int get_path()
{
	vector <int> parent(counter+1,-1);
	parent[0]=0;
	stack <int> dfs;
	dfs.push(0);
	while(!dfs.empty())
	{
		int top=dfs.top();
		dfs.pop();
		if(top==counter)
			break;
		for (int i = 0; i <= counter; ++i)
		{
			if(flo[top][i] && parent[i]==-1)
			{
				parent[i]=top;
				dfs.push(i);
			}
		}
	}
	if(parent[counter]==-1)
		return 0;
	int ans=10000,pos=counter;
	while(pos!=0)
	{
		ans=min(ans,flo[parent[pos]][pos]);
		pos=parent[pos];
	}
	pos=counter;
	while(pos!=0)
	{
		flo[parent[pos]][pos]-=ans;
		flo[pos][parent[pos]]+=ans;
		pos=parent[pos];
	}
	return ans;
}
int main()
{
	// freopen("input.txt","r",stdin);
	scanf("%d %d",&n,&t);
	char inp[n][n+1];
	for (int i = 0; i < n; ++i)
	{
		scanf("%s",inp[i]);
	}
	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < n; ++j)
		{
			if(inp[i][j]=='Y' || inp[i][j]=='Z')
			{
				plant[i][j][0]=inp[i][j]-'X';
				source_cap[i][j]=0;
			}
			else
			{
				plant[i][j][0]=0;
				source_cap[i][j]=inp[i][j]-'0';
			}
		}
	}
	for (int i = 0; i < n; ++i)
	{
		scanf("%s",inp[i]);
	}
	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < n; ++j)
		{
			if(inp[i][j]=='Y' || inp[i][j]=='Z')
			{
				plant[i][j][0]=inp[i][j]-'X';
				sink_cap[i][j]=0;
			}
			else
			{
				plant[i][j][0]=0;
				sink_cap[i][j]=inp[i][j]-'0';
			}
		}
	}
	for (int curr_time = 1; curr_time <= t; ++curr_time)
	{
		for (int i = 0; i < n; ++i)
		{
			for (int j = 0; j < n; ++j)
			{
				plant[i][j][curr_time]=plant[i][j][curr_time-1];
			}
		}
		for (int i = 0; i < n; ++i)
		{
			for (int j = 0; j < n; ++j)
			{
				if(plant[i][j][curr_time-1]==2)
				{
					for (int k = 0; k < 4; ++k)
					{
						if(is_valid(i+dr[k],j+dc[k]))
						{
							if(plant[i+dr[k]][j+dc[k]][curr_time-1]==0)
								plant[i+dr[k]][j+dc[k]][curr_time]=2;
						}
					}
				}
			}
		}
	}
	counter=1;
	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < n; ++j)
		{
			if(source_cap[i][j]!=0)
			{
				source_num[i][j]=counter;
				counter++;
			}
			else
				source_num[i][j]=-1;
		}
	}
	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < n; ++j)
		{
			if(sink_cap[i][j]!=0)
			{
				sink_num[i][j]=counter;
				counter++;
			}
			else
				sink_num[i][j]=-1;
		}
	}
	queue < pair <int,pair <int,int> > > bfs;
	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < n; ++j)
		{
			if(source_cap[i][j]==0)
				continue;
			bfs.push(pair <int,pair <int,int> > (0,pair <int,int> (i,j)));
			int source=source_num[i][j];
			vector < vector <bool> > vis(n,vector <bool> (n,false));
			vis[i][j]=true;
			while(!bfs.empty())
			{
				pair <int, pair <int,int> > top=bfs.front();
				bfs.pop();
				int curr_time=top.first,r=(top.second).first,c=(top.second).second;
				if(sink_cap[r][c]!=0)
					flo[source][sink_num[r][c]]=10000;
				if(curr_time==t)
					continue;
				if(plant[r][c][curr_time]!=0)
					continue;
				for (int k = 0; k < 4; ++k)
				{
					if(is_valid(r+dr[k],c+dc[k]) && plant[r+dr[k]][c+dc[k]][curr_time]==0 && !vis[r+dr[k]][c+dc[k]])
					{
						bfs.push(pair <int, pair <int,int> >(curr_time+1,pair <int,int> (r+dr[k],c+dc[k])));
						vis[r+dr[k]][c+dc[k]]=true;
					}
				}
			}
		}
	}
	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < n; ++j)
		{
			if(source_cap[i][j]!=0)
				flo[0][source_num[i][j]]=source_cap[i][j];
			if(sink_cap[i][j]!=0)
				flo[sink_num[i][j]][counter]=sink_cap[i][j];
		}
	}
	int temp,ans=0;
	while(true)
	{
		temp=get_path();
		if(temp==0)
			break;
		ans+=temp;
	}
	cout<<ans;
	return 0;
}
